const row = $json;

const scriptRunId = String(row.script_run_id ?? '').trim();
const topic = String(row.topic ?? '').trim();
const languageCode = String(row.language_code ?? '').trim();
const duration = Number(row.target_duration_seconds);

let evidence = row.evidence_json;
if (typeof evidence === 'string') {
  evidence = JSON.parse(evidence);
}

if (
  !scriptRunId ||
  !topic ||
  !['en','pl','ru','uk'].includes(languageCode) ||
  ![15,30,45,60].includes(duration) ||
  !Array.isArray(evidence) ||
  evidence.length < 3
) {
  throw new Error('begin_script returned invalid context');
}

const languageNames = {
  en: 'English',
  pl: 'Polish',
  ru: 'Russian',
  uk: 'Ukrainian',
};

const speechRate = {
  en: { min: 1.8, max: 2.6, target: 2.2 },
  pl: { min: 1.4, max: 2.2, target: 1.8 },
  ru: { min: 1.3, max: 2.1, target: 1.7 },
  uk: { min: 0.6, max: 2.4, target: 1.5 },
}[languageCode];

const wordMin = Math.ceil(duration * speechRate.min);
const wordMax = Math.floor(duration * speechRate.max);
const targetWords = Math.round(duration * speechRate.target);
const minSceneWords = 2;
const maxSceneWords = duration <= 15 ? 10 : 14;

const targetSegments = {
  15: 5,
  30: 9,
  45: 13,
  60: 17,
}[duration];

const density = {
  targetScenes: targetSegments,
  targetShots: targetSegments,
};

const evidenceMap = {};
const promptEvidence = evidence.map((entry) => {
  const ref = String(entry.evidence_ref ?? '').trim();
  const uuid = String(entry.evidence_uuid ?? '').trim();
  if (!/^E[1-9][0-9]*$/.test(ref) || !/^[0-9a-f-]{36}$/i.test(uuid)) {
    throw new Error('invalid evidence reference from database');
  }
  evidenceMap[ref] = uuid;
  return {
    id: ref,
    source_domain: String(entry.source_domain ?? ''),
    title: String(entry.title ?? ''),
    source_url: String(entry.source_url ?? ''),
    snippet: String(entry.snippet ?? ''),
    content: String(entry.content ?? ''),
  };
});

const systemMessage = [
  'You create factual short-form video scripts and executable visual storyboards.',
  'Use ONLY the evidence provided in the user message.',
  'Do not use outside knowledge, hidden memory, Google Search, URL fetching, or assumptions.',
  'Every scene narration must be supported by one or more evidence IDs from the supplied evidence list.',
  'If the supplied evidence cannot support a complete factual script, return JSON object {"error":"INSUFFICIENT_EVIDENCE"} and nothing else.',
  'Return valid JSON only. No markdown, comments, or prose outside JSON.',
].join(' ');

const contract = {
  narration: 'continuous narration in the requested output language',
  scenes: [
    {
      scene_id: 'S1',
      narration: 'exact contiguous narration segment',
      evidence_ids: ['E1'],
      shots: [
        {
          shot_id: 'S1-A',
          visual_intent: 'concrete visible subject/action/mechanism in English',
          must_show: ['concrete required visual concept'],
          must_not_show: ['specific conflicting visual if relevant'],
          queries_en: ['precise technical query', 'broader physical fallback query', 'encyclopedic synonym query'],
          preferred_media_type: 'photo',
        },
      ],
    },
  ],
};

const userMessage = [
  'TOPIC: ' + topic,
  'OUTPUT LANGUAGE: ' + languageNames[languageCode] + ' (' + languageCode + ')',
  'TARGET DURATION: ' + duration + ' seconds',
  'NARRATION WORD RANGE: ' + wordMin + '-' + wordMax + ' words',
  'TARGET NARRATION WORD COUNT: exactly ' + targetWords + ' words if possible; never exceed the allowed range',
  'EXACT SCENE COUNT: ' + density.targetScenes,
  'EXACT TOTAL SHOT COUNT: ' + density.targetShots,
  '',
  'OUTPUT CONTRACT:',
  JSON.stringify(contract),
  '',
  'RULES:',
  '- narration must equal all scene narration strings joined in scene order with one space;',
  '- scene_id values must be sequential S1, S2, S3...;',
  '- every scene must cite 1-4 valid evidence_ids from the supplied list;',
  '- each scene must contain exactly 1 shot;',
  '- each scene narration must be an exact contiguous segment of the continuous narration with ' + minSceneWords + '-' + maxSceneWords + ' words; scene boundaries MAY occur inside a sentence because they are visual cut points, so a segment may start lowercase or end with comma/no terminal punctuation; the joined scene narrations must form natural complete narration that starts normally and ends with . ! ? or …;',
  '- if a scene narration segment begins with a relative/anaphoric word such as which/that/it, który/która/które, который/которая/которое, який/яка/яке, first resolve what noun/result the pronoun actually refers to; do NOT assume it refers to the previous shot primary when the previous narration introduced another referent after that primary; if it does refer to the previous visual primary, keep that primary unless the current segment explicitly names a new concrete primary; never switch to an object unrelated to the actual referent/current clause;',
  '- visual metadata must be grounded in the current narration segment plus the immediately preceding unfinished clause when the scene cut occurs inside one sentence;',
  '- shot_id must start with its scene_id, for example S2-A or S2-B;',
  '- each shot must have a concrete visual_intent, at least one must_show concept, and exactly 3 distinct English queries;',
  '- CRITICAL LANGUAGE SPLIT: narration/scenes use OUTPUT LANGUAGE, but ALL visual metadata fields (visual_intent, every must_show item, every must_not_show item, and every queries_en item) MUST be written in English only regardless of OUTPUT LANGUAGE;',
  '- never translate visual metadata into Polish, Russian, or Ukrainian; only spoken narration uses the requested non-English language;',

  "- visual_intent must prefer a directly searchable real physical subject/result; for a specialized process, show the exact equipment if common, otherwise show the immediate physical input/output that proves the step;",
  "- must_show must contain 1-3 SHORT independent English visual anchors, each 1-3 words; do not put a whole sentence/action phrase in one must_show item;",
  "- must_show[0] must identify the concrete main subject of the narration: use the complete common name of the whole object, organism, equipment, place, or visible material; never a detached body part, generic droplet/texture, action, or hidden reaction when the scene is about a larger identifiable subject;",
  "- prefer ONE precise identifying must_show anchor; add another only when essential to distinguish the visible subject, not for decoration, background, camera angle or invisible/internal details. Every supplied anchor is a requirement, not an optional keyword.",
  '- secondary must_show anchors must add an independent visible subject/context; never restate, synonymize, or describe a component/detail of must_show[0] (for example water turbine + turbine blades);',
  "- when the narrated process is invisible inside an object or organism, show that same object or organism in relevant physical context. Do not invent a visibly different substitute that merely shares a texture or broad scientific category.",
  "- when a flow/current/reaction happens through or inside a CLOSED conduit or machine, make that conduit/machine the primary must_show; do not require hidden contents/process to be visible unless visual_intent explicitly says transparent/open/cutaway/exposed.",
  "- avoid generic secondary anchors when a more specific visible subject is available, but do not invent equipment that is not supported by the narration or evidence;",
  "- must_show[0] MUST be a concrete searchable physical subject, material, object, place, equipment item, or visible result that should actually appear in the frame; never use only an abstract process, action, or generic descriptor as must_show[0];",
  '- put optional context, process, location, material, result, or equipment anchors after the primary physical subject;',
  "- queries_en items 1 and 2 must contain at least one distinctive term from must_show[0]; query 3 is the robust physical-subject fallback and must center must_show[0];",
  "- queries_en must contain exactly 3 distinct English queries: (1) precise process/equipment anchored to must_show[0], (2) broader process/result query anchored to must_show[0], (3) must_show[0] itself as a short 1-4 word physical-subject fallback; process specificity belongs in queries 1 and 2;",
  "- at least two of the three queries must contain a distinctive term from the primary subject or a specific contextual anchor, not only generic words;",
  "- avoid the word photo in queries unless it is part of an established proper phrase; search nouns are more important than presentation words;",
  '- must_show must describe directly visible objects, equipment, materials, attributes, actions, or physical results that can be verified in a real photo/video;',
  '- each English query must be concise, factual, concrete, and 2-10 words and must describe what should literally be visible;',
  '- avoid generic filler queries such as beautiful/stunning scenery, nature background, wallpaper, or broad topic-only searches;',
  '- preferred_media_type must be photo only; use a real photograph of the exact object, equipment, material, place, or physical result described;',
  '- prioritize semantic accuracy over motion; do not request video in this production mode;',
  '- when narration describes an invisible mechanism, choose a real physical object, machine, experiment, process step, or visible result that directly represents it instead of a text explanation card;',
  '- for invisible or abstract mechanisms, anchor the visual to a concrete supported object, apparatus, material, location, or visible result rather than an abstract label;',
  '- every query must include enough specific qualifiers to disambiguate ambiguous nouns and keep the search tied to the intended visible subject;',
  '- if a likely visual confusion exists, populate must_not_show with concise conflicting visible concepts;',
  '- never replace a technical process with decorative stock imagery;',
  '- do not use filler search words such as stunning, beautiful, scenery, wallpaper, aesthetic, background, cinematic, generic nature, icon, vector, clipart, illustration, diagram, schematic, or infographic;',
  '- never name a media provider, asset ID, URL, filename, or preselected image/video in a shot;',
  '- preferred_media_type must be exactly photo;',
  '- every scene must directly advance the answer to TOPIC; evidence-supported side facts are still forbidden when they do not help answer TOPIC;',
  '- do not spend a scene on generic praise, benefits, environmental/economic impact, history, outro, summary, or broad context unless TOPIC explicitly asks for that aspect;',
  '- for how/process/mechanism topics, keep a causal/operational sequence from input or condition through mechanism/components to the final output/result; the last scene must complete that mechanism/result instead of switching to generic benefits;',
  '- each scene must add a distinct necessary fact; never repeat the same causal step or paraphrase another scene merely to fill the required scene count;',
  '- do not add facts that are not supported by the cited evidence IDs;',
  '- do not mention evidence IDs in the spoken narration;',
  '- make narration natural, idiomatic, and native-sounding in the requested language for one continuous voiceover; avoid code-switching and words borrowed from another requested-language variant;',
  '- for Ukrainian output, use standard Ukrainian vocabulary only; do not insert Russian lexical forms;',
  '- count the narration words before returning JSON; target exactly ' + targetWords + ' words and never return outside ' + wordMin + '-' + wordMax + ' words;',
  '- do not underfill the narration: when a character range is supplied, prefer the middle of that range rather than the minimum;',
  '',
  'EVIDENCE:',
  JSON.stringify(promptEvidence),
].join('\n');

return {
  json: {
    script_run_id: scriptRunId,
    model: 'gemini-3.5-flash-lite',
    topic,
    language_code: languageCode,
    target_duration_seconds: duration,
    word_min: wordMin,
    word_max: wordMax,
    target_words: targetWords,
    target_scenes: density.targetScenes,
    target_shots: density.targetShots,
    evidence_map: evidenceMap,
    system_message: systemMessage,
    user_message: userMessage,
  },
};

const providerError = $json && $json.error;
if (providerError) {
  const providerMessage = String(
    providerError.description ||
    providerError.message ||
    'Gemini provider request failed'
  );
  throw new Error(
    'Gemini provider failed after transient retries: ' + providerMessage
  );
}

const ctx = $('Build Script Prompt').first().json;
const response = $json ?? {};

const statusCode = Number(response.statusCode ?? response.status ?? 0);
if (statusCode < 200 || statusCode > 299) {
  const providerMessage =
    response.body?.error?.message ??
    response.error?.message ??
    response.message ??
    'Gemini request failed';
  throw new Error('Gemini HTTP ' + statusCode + ': ' + String(providerMessage));
}

const body = response.body && typeof response.body === 'object'
  ? response.body
  : response;

const candidate = Array.isArray(body.candidates) ? body.candidates[0] : null;
const parts = Array.isArray(candidate?.content?.parts) ? candidate.content.parts : [];
const rawText = parts
  .filter((part) => part && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('Gemini returned no text content');
}

const normalizedRawText = rawText;

const parseModelJson = (value) => {
  const original = String(value ?? '').trim();
  const text = original
    .replace(/^\x60\x60\x60(?:json)?\s*/iu, '')
    .replace(/\s*\x60\x60\x60$/u, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (primaryError) {
    let start = -1;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === '{' || text[i] === '[') {
        start = i;
        break;
      }
    }
    if (start < 0 || text.slice(0,start).trim()) {
      throw primaryError;
    }

    const stack = [];
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];

      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (ch === '\\') {
          escaped = true;
          continue;
        }
        if (ch === '"') inString = false;
        continue;
      }

      if (ch === '"') {
        inString = true;
        continue;
      }

      if (ch === '{' || ch === '[') {
        stack.push(ch);
        continue;
      }

      if (ch === '}' || ch === ']') {
        if (!stack.length) break;
        const open = stack[stack.length - 1];
        if (
          (open === '{' && ch !== '}') ||
          (open === '[' && ch !== ']')
        ) {
          throw primaryError;
        }
        stack.pop();

        if (!stack.length) {
          const candidate = text.slice(start,i + 1);
          const remainder = text.slice(i + 1).trim();
          if (remainder && !/^[}\]\s]+$/u.test(remainder)) {
            throw primaryError;
          }
          return JSON.parse(candidate);
        }
      }
    }

    throw primaryError;
  }
};

let parsed;
try {
  parsed = parseModelJson(normalizedRawText);
} catch (error) {
  throw new Error('Gemini returned invalid JSON: ' + error.message);
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('Gemini storyboard root must be an object');
}
if (parsed.error) {
  throw new Error('Gemini could not build storyboard: ' + String(parsed.error));
}

const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const narration = clean(parsed.narration);
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];

if (scenes.length !== Number(ctx.target_scenes)) {
  throw new Error(
    'scene count mismatch: ' + scenes.length +
    ', required exactly ' + ctx.target_scenes
  );
}

const evidenceMap = ctx.evidence_map && typeof ctx.evidence_map === 'object'
  ? ctx.evidence_map
  : {};
const allowedEvidence = new Set(Object.keys(evidenceMap));
const allowedMedia = new Set(['photo']);
const providerPattern = /\b(pexels|pixabay|wikimedia|unsplash|openverse)\b|https?:\/\//i;

// ENGLISH_VISUAL_METADATA_GUARD_START
function assertEnglishVisualMetadata(ctx, shotId, visualIntent, mustShow, mustNotShow, queries) {
  const languageCode = String(ctx.language_code ?? '').trim();
  const fields = [
    String(visualIntent ?? ''),
    ...(Array.isArray(mustShow) ? mustShow : []),
    ...(Array.isArray(mustNotShow) ? mustNotShow : []),
    ...(Array.isArray(queries) ? queries : []),
  ].map((value) => String(value ?? '').trim()).filter(Boolean);
  const combined = fields.join(' ');

  if (languageCode === 'pl' && /[ąćęłńóśźż]/iu.test(combined)) {
    throw new Error(shotId + ' visual metadata must be English; Polish characters detected');
  }
  if ((languageCode === 'ru' || languageCode === 'uk') && /[\u0400-\u04ff]/u.test(combined)) {
    throw new Error(shotId + ' visual metadata must be English; Cyrillic detected');
  }

  const tokens = (value) => String(value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/u)
    .filter((token) => token.length >= 2);

  const generic = new Set([
    'the','and','for','with','from','into','onto','over','under','this','that',
    'show','showing','view','close','macro','image','photo','video','scene',
    'concrete','real','visible','large','small','modern','industrial',
    'object','item','thing','system','process','action','result','background',
  ]);
  const intentTerms = new Set(
    tokens(visualIntent).filter((token) => !generic.has(token))
  );
  const primaryTerms = tokens(Array.isArray(mustShow) ? mustShow[0] : '')
    .filter((token) => !generic.has(token));

  if (
    languageCode !== 'en' &&
    primaryTerms.length > 0 &&
    !primaryTerms.some((term) => intentTerms.has(term))
  ) {
    throw new Error(
      shotId +
      ' visual metadata must be English and primary must_show must match English visual_intent'
    );
  }
}
// ENGLISH_VISUAL_METADATA_GUARD_END

// MUST_SHOW_SECONDARY_GUARD_START
function normalizeMustShowAnchors(rawMustShow, visualIntent='') {
  const words = (value) => String(value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/u)
    .filter(Boolean);

  const secondaryGeneric = new Set([
    'thing','item','object','device','equipment','machine','machinery','tool','system',
    'process','action','method','technology','material','surface','area',
    'place','location','result','product','structure','environment',
    'background','scene','facility','component','part','detail','mechanism','industrial','technical','mechanical'
  ]);

  const secondaryProcessHeads = new Set([
    'flow','motion','movement','rotation','current','electricity','energy',
    'power','pressure','force','generation','distribution','transmission'
  ]);
  const secondaryActionTerms = new Set([
    'flow','flowing','spin','spinning','rotate','rotating','rotation',
    'move','moving','movement','turn','turning','fall','falling',
    'rush','rushing','motion','current','electricity','energy',
    'power','pressure','force','generation','distribution','transmission'
  ]);
  const concealedPathHeads = new Set([
    'pipe','pipeline','penstock','tube','duct','hose','conduit','cable','wire',
    'reactor','engine','motor','turbine','pump','compressor','generator',
    'transformer','tank','vessel','chamber','filter','valve','nozzle',
    'artery','vein'
  ]);
  const visibilityOverrides = new Set([
    'transparent','glass','open','opened','cutaway','exposed'
  ]);

  const anchors = (Array.isArray(rawMustShow) ? rawMustShow : [])
    .map((anchor) => String(anchor ?? '').trim())
    .filter(Boolean);
  let primary = anchors[0] || '';
  let remaining = anchors.slice(1);

  const primaryTerms = words(primary);
  const primaryProcessLike = primaryTerms.some((word) => secondaryActionTerms.has(word));
  const normalizedIntentWords = words(visualIntent);
  const normalizedIntent = normalizedIntentWords.join(' ');
  const explicitlyVisibleInside = normalizedIntentWords.some((word) =>
    visibilityOverrides.has(word)
  );

  if (primaryProcessLike && !explicitlyVisibleInside) {
    const promotable = remaining.find((anchor) => {
      const anchorTerms = words(anchor).filter((word) => !secondaryGeneric.has(word));
      if (!anchorTerms.length) return false;
      const head = anchorTerms[anchorTerms.length - 1];
      if (!concealedPathHeads.has(head)) return false;
      const phrase = words(anchor).join(' ');
      if (!phrase) return false;
      const patterns = [
        'through ' + phrase,
        'through a ' + phrase,
        'through an ' + phrase,
        'through the ' + phrase,
        'inside ' + phrase,
        'inside a ' + phrase,
        'inside an ' + phrase,
        'inside the ' + phrase,
        'within ' + phrase,
        'within a ' + phrase,
        'within an ' + phrase,
        'within the ' + phrase,
        'into ' + phrase,
        'into a ' + phrase,
        'into an ' + phrase,
        'into the ' + phrase,
      ];
      const padded = ' ' + normalizedIntent + ' ';
      return patterns.some((pattern) => padded.includes(' ' + pattern + ' '));
    });

    if (promotable) {
      primary = promotable;
      remaining = remaining.filter((anchor) => anchor !== promotable);
    }
  }

  const primaryWordList = words(primary);
  const primaryWords = new Set(primaryWordList);
  const primaryHead = primaryWordList[primaryWordList.length - 1] || '';
  const primaryConcealsInternalProcess =
    concealedPathHeads.has(primaryHead) && !explicitlyVisibleInside;
  const intentWords = new Set(
    words(visualIntent).filter((word) => !secondaryGeneric.has(word))
  );
  const secondary = remaining
    .filter((anchor) => {
      const anchorTerms = words(anchor).filter((word) => !secondaryGeneric.has(word));
      if (!anchorTerms.length) return false;
      if (secondaryProcessHeads.has(anchorTerms[anchorTerms.length - 1])) return false;
      if (
        primaryConcealsInternalProcess &&
        anchorTerms.some((word) => secondaryActionTerms.has(word))
      ) return false;
      const concreteAnchorTerms = anchorTerms.filter((word) => !secondaryActionTerms.has(word));
      if (!concreteAnchorTerms.length) return false;
      if (concreteAnchorTerms.some((word) => primaryWords.has(word))) return false;
      if (!concreteAnchorTerms.some((word) => intentWords.has(word))) return false;
      return true;
    });

  return [primary, ...secondary].filter(Boolean);
}
// MUST_SHOW_SECONDARY_GUARD_END


// SHORT_MUST_SHOW_GUARD_START
const shortMustShowPrefixPairs = new Set([
  'high voltage',
  'low voltage',
  'high pressure',
  'low pressure',
]);
const shortMustShowLeadingModifiers = new Set([
  'large','small','modern','industrial','technical','mechanical',
]);
function normalizeShortDomainAnchor(value) {
  const original = String(value ?? '').replace(/\s+/g,' ').trim();
  let parts = original.split(/\s+/u).filter(Boolean);
  if (parts.length <= 3) return original;

  while (parts.length > 3) {
    const pair = parts.slice(0,2).map((word) => word.toLowerCase()).join(' ');
    if (shortMustShowPrefixPairs.has(pair)) {
      parts = parts.slice(2);
      continue;
    }
    if (shortMustShowLeadingModifiers.has(String(parts[0] || '').toLowerCase())) {
      parts = parts.slice(1);
      continue;
    }
    break;
  }
  return parts.join(' ');
}
// SHORT_MUST_SHOW_GUARD_END

function startsWithInheritedReferent(value, languageCode) {
  const text = String(value ?? '').trim().toLowerCase();
  const patterns = {
    en: /^(which|that|it|its|they|their|them|whose)\b/u,
    pl: /^(który|która|które|którzy|których|którego|której|którym|którą|któremu|jego|jej|ich)\b/u,
    ru: /^(который|которая|которое|которые|которого|которой|которым|он|она|оно|они|его|её|их)\b/u,
    uk: /^(який|яка|яке|які|якого|якої|яким|він|вона|воно|вони|його|її|їх)\b/u,
  };
  return (patterns[String(languageCode ?? '').trim()] ?? patterns.en).test(text);
}

function visualPrimarySubjectTerms(value) {
  const generic = new Set([
    'electric','electrical','large','small','modern','industrial','technical',
    'mechanical','high','low','power','water','hydroelectric','steam',
    'machine','equipment','unit','system','device','apparatus'
  ]);
  return String(value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/u)
    .filter((term) => term.length >= 3 && !generic.has(term));
}

function inheritedVisualSubjectMatches(previousPrimary,currentPrimary) {
  const previous = visualPrimarySubjectTerms(previousPrimary);
  const current = new Set(visualPrimarySubjectTerms(currentPrimary));
  return previous.length > 0 && previous.some((term) => current.has(term));
}

function transliterateCyrillicVisualLexeme(value) {
  const map = {
    'а':'a','б':'b','в':'v','г':'g','ґ':'g','д':'d','е':'e','ё':'e',
    'є':'ye','ж':'zh','з':'z','и':'i','і':'i','ї':'yi','й':'y',
    'к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r',
    'с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch',
    'ш':'sh','щ':'shch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'
  };
  return [...String(value ?? '').toLowerCase()]
    .map((char) => map[char] ?? char)
    .join('');
}

function normalizedNarrationVisualWords(value) {
  return transliterateCyrillicVisualLexeme(
    String(value ?? '')
      .toLowerCase()
      .normalize('NFKD')
      .replace(/\p{M}+/gu,'')
  )
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/u)
    .filter(Boolean);
}

function visualPrimaryTermMatchesNarrationWord(primaryTerm,word) {
  const term=String(primaryTerm ?? '').toLowerCase();
  const token=String(word ?? '').toLowerCase();
  if (!term || !token) return false;
  if (token === term) return true;
  if (term.length >= 6 && token.startsWith(term)) return true;

  // Conservative cognate handling for supported PL/RU/UK narration.
  // Example: turbine -> turbiny/turbina; transformer -> transformator.
  if (
    term.length >= 6 &&
    term.endsWith('e') &&
    token.startsWith(term.slice(0,-1))
  ) {
    return true;
  }
  if (
    term === 'transformer' &&
    token.startsWith('transformator')
  ) {
    return true;
  }
  return false;
}

function narrationExplicitlyMentionsVisualPrimary(narration,currentPrimary) {
  const primaryTerms = visualPrimarySubjectTerms(currentPrimary);
  if (!primaryTerms.length) return false;
  const narrationTerms = normalizedNarrationVisualWords(narration);

  return primaryTerms.some((primaryTerm) =>
    narrationTerms.some((word) =>
      visualPrimaryTermMatchesNarrationWord(primaryTerm,word)
    )
  );
}

function previousVisualPrimaryIsLikelyTerminalAntecedent(
  previousNarration,
  previousPrimary
) {
  const primaryTerms = visualPrimarySubjectTerms(previousPrimary);
  if (!primaryTerms.length) return true;

  const narrationTerms = normalizedNarrationVisualWords(previousNarration);
  const matchingIndexes=[];
  narrationTerms.forEach((word,index) => {
    if (
      primaryTerms.some((primaryTerm) =>
        visualPrimaryTermMatchesNarrationWord(primaryTerm,word)
      )
    ) {
      matchingIndexes.push(index);
    }
  });

  // If lexical grounding cannot be located, stay fail-closed.
  if (!matchingIndexes.length) return true;

  // Only treat the previous visual primary as the inherited referent when
  // its latest lexical mention is the terminal word of that narration cut.
  return Math.max(...matchingIndexes) === narrationTerms.length - 1;
}


const sanitizedScenes = [];
const globalShotIds = new Set();
let totalShots = 0;

for (let i = 0; i < scenes.length; i++) {
  const scene = scenes[i];
  if (!scene || typeof scene !== 'object' || Array.isArray(scene)) {
    throw new Error('scene ' + (i + 1) + ' must be an object');
  }

  const expectedSceneId = 'S' + (i + 1);
  const sceneId = clean(scene.scene_id);
  if (sceneId !== expectedSceneId) {
    throw new Error('scene_id must be sequential: expected ' + expectedSceneId);
  }

  const sceneNarration = clean(scene.narration);
  if (!sceneNarration) {
    throw new Error(sceneId + ' narration is empty');
  }
  const sceneWords = sceneNarration.split(/\s+/u).filter(Boolean);
  const minSceneWords = 2;
  const maxSceneWords = Number(ctx.target_duration_seconds) <= 15 ? 10 : 14;
  if (sceneWords.length < minSceneWords) {
    throw new Error(
      sceneId + ' narration is too short for a semantic scene: ' +
      sceneWords.length + ', minimum ' + minSceneWords
    );
  }
  if (sceneWords.length > maxSceneWords) {
    throw new Error(
      sceneId + ' narration is too long for visual pacing: ' +
      sceneWords.length + ', maximum ' + maxSceneWords
    );
  }
  if (!/[\p{L}\d]/u.test(sceneNarration)) {
    throw new Error(sceneId + ' narration segment has no lexical content');
  }

  const evidenceIds = Array.isArray(scene.evidence_ids)
    ? scene.evidence_ids.map(clean)
    : [];
  const uniqueEvidence = [...new Set(evidenceIds)];
  if (
    uniqueEvidence.length < 1 ||
    uniqueEvidence.length > 4 ||
    uniqueEvidence.length !== evidenceIds.length ||
    uniqueEvidence.some((id) => !allowedEvidence.has(id))
  ) {
    throw new Error(sceneId + ' has invalid evidence_ids');
  }

  const shots = Array.isArray(scene.shots) ? scene.shots : [];
  if (shots.length !== 1) {
    throw new Error(sceneId + ' must contain exactly 1 shot');
  }

  const sanitizedShots = [];
  for (let j = 0; j < shots.length; j++) {
    const shot = shots[j];
    if (!shot || typeof shot !== 'object' || Array.isArray(shot)) {
      throw new Error(sceneId + ' shot ' + (j + 1) + ' must be an object');
    }

    const shotId = clean(shot.shot_id);
    const expectedSuffix = String.fromCharCode(65 + j);
    const expectedShotId = sceneId + '-' + expectedSuffix;
    if (shotId !== expectedShotId || globalShotIds.has(shotId)) {
      throw new Error('invalid or duplicate shot_id: ' + shotId);
    }
    globalShotIds.add(shotId);

    const visualIntent = clean(shot.visual_intent);
    if (visualIntent.length < 12 || visualIntent.length > 400) {
      throw new Error(shotId + ' visual_intent is invalid');
    }

    const rawMustShow = Array.isArray(shot.must_show)
      ? shot.must_show.map(clean).filter(Boolean).map(normalizeShortDomainAnchor)
      : [];
    const mustNotShow = Array.isArray(shot.must_not_show)
      ? shot.must_not_show.map(clean).filter(Boolean)
      : [];
    if (rawMustShow.length < 1 || rawMustShow.length > 3 || mustNotShow.length > 6) {
      throw new Error(shotId + ' must_show/must_not_show is invalid');
    }
    if (rawMustShow.some((item) => {
      const count = item.split(/\s+/u).filter(Boolean).length;
      return count < 1 || count > 3 || item.length > 60;
    })) {
      throw new Error(shotId + ' must_show items must be short domain anchors');
    }

    const primaryGeneric = new Set([
      'thing','item','object','generic','concept','process','action','method',
      'system','technology','material','surface','area','scene','background',
      'environment','result','product','component','part'
    ]);
    const secondaryGeneric = new Set([
      'thing','item','object','device','equipment','machine','tool','system',
      'process','action','method','technology','material','surface','area',
      'place','location','result','product','structure','environment',
      'background','scene','facility','component','part'
    ]);
    const anchorWords = (value) => String(value || '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g,' ')
      .split(/\s+/u)
      .filter(Boolean);

    const sourceQueries = Array.isArray(shot.queries_en)
      ? shot.queries_en.map(clean).filter(Boolean)
      : [];
    if (sourceQueries.length !== 3) {
      throw new Error(shotId + ' queries_en is invalid');
    }

    assertEnglishVisualMetadata(
      ctx,
      shotId,
      visualIntent,
      rawMustShow,
      mustNotShow,
      sourceQueries
    );

    const mustShow = normalizeMustShowAnchors(rawMustShow, visualIntent);

    const primaryWords = anchorWords(mustShow[0]);
    const primaryTerms = primaryWords.filter(
      (word) => !primaryGeneric.has(word)
    );
    if (primaryTerms.length < 1) {
      throw new Error(
        shotId + ' must_show[0] lacks a concrete/searchable primary subject or exact equipment anchor'
      );
    }

    const processGeneric = secondaryGeneric;
    const secondaryTerms = mustShow
      .slice(1)
      .flatMap(anchorWords)
      .filter((word) => !processGeneric.has(word));

    const queries = sourceQueries.map((query,index) => {
      const words = query.split(/\s+/u).filter(Boolean);
      const lower = new Set(words.map((word) => word.toLowerCase()));

      if (index === 2) {
        if (!secondaryTerms.length) {
          const hasPrimary = primaryTerms.some((term) => lower.has(term));
          if (hasPrimary || primaryTerms.length === 0) return query;
          return mustShow[0];
        }

        const hasSecondary = secondaryTerms.some((term) => lower.has(term));
        if (hasSecondary) return query;

        const primaryHint = primaryTerms.length
          ? primaryTerms[primaryTerms.length - 1]
          : '';
        const fallbackTerms = secondaryTerms.length >= 2
          ? secondaryTerms.slice(0,3)
          : [primaryHint, secondaryTerms[0]].filter(Boolean);
        return fallbackTerms.join(' ');
      }

      const hasPrimary = primaryTerms.some((term) => lower.has(term));
      if (hasPrimary || primaryTerms.length === 0) return query;

      const room = Math.max(0, 10 - primaryTerms.length);
      const baseWords = words.slice(0, room);
      return [...baseWords, ...primaryTerms].join(' ');
    });

    if (
      queries.slice(0,2).some(
        (query) => query.toLowerCase() === queries[2].toLowerCase()
      )
    ) {
      const suffix = secondaryTerms[0] || 'detail';
      queries[2] = (queries[2] + ' ' + suffix).trim();
    }

    const queryKeys = queries.map((q) => q.toLowerCase());
    if (
      queries.length !== 3 ||
      new Set(queryKeys).size !== queries.length ||
      queries.some((query,index) => {
        const count = query.split(/\s+/u).filter(Boolean).length;
        const minWords = index === 2 ? 1 : 2;
        return count < minWords || count > 10 || query.length > 120;
      })
    ) {
      throw new Error(shotId + ' queries_en is invalid');
    }

    if (
      i > 0 &&
      startsWithInheritedReferent(sceneNarration,ctx.language_code)
    ) {
      const previousPrimary = String(
        sanitizedScenes[i - 1]?.shots?.[0]?.must_show?.[0] ?? ''
      ).trim();
      const currentPrimary = String(mustShow[0] ?? '').trim();
      const previousNarration = String(
        sanitizedScenes[i - 1]?.narration ?? ''
      ).trim();
      const inheritedRestrictionApplies =
        previousVisualPrimaryIsLikelyTerminalAntecedent(
          previousNarration,
          previousPrimary
        );
      const preservesInheritedPrimary =
        inheritedVisualSubjectMatches(previousPrimary,currentPrimary);
      const explicitlyNamesCurrentPrimary =
        narrationExplicitlyMentionsVisualPrimary(
          sceneNarration,
          currentPrimary
        );
      if (
        !previousPrimary ||
        !currentPrimary ||
        (
          inheritedRestrictionApplies &&
          !preservesInheritedPrimary &&
          !explicitlyNamesCurrentPrimary
        )
      ) {
        throw new Error(
          shotId +
          ' anaphoric scene visual subject must preserve the likely inherited previous primary or explicitly name a new current primary: ' +
          previousPrimary + ' -> ' + currentPrimary
        );
      }
    }

    const preferredMediaType = clean(shot.preferred_media_type).toLowerCase();
    if (!allowedMedia.has(preferredMediaType)) {
      throw new Error(shotId + ' preferred_media_type is invalid');
    }

    const queryFillerPattern = /\b(stunning|beautiful|scenery|wallpaper|aesthetic|background|cinematic|icon|vector|clipart|illustration|diagram|schematic|infographic|text card)\b/i;
    const visualNonPhotoPattern = /\b(wallpaper|icon|vector|clipart|illustration|diagram|schematic|infographic|text card)\b/i;
    if (
      queries.some((query) => queryFillerPattern.test(query)) ||
      visualNonPhotoPattern.test(visualIntent)
    ) {
      throw new Error(shotId + ' contains generic/non-photographic visual request');
    }

    const antiSelectionText = [
      visualIntent,
      ...mustShow,
      ...mustNotShow,
      ...queries,
    ].join(' ');
    if (providerPattern.test(antiSelectionText)) {
      throw new Error(shotId + ' contains provider/URL preselection');
    }

    sanitizedShots.push({
      shot_id: shotId,
      visual_intent: visualIntent,
      must_show: mustShow,
      must_not_show: mustNotShow,
      queries_en: queries,
      preferred_media_type: preferredMediaType,
    });
  }

  totalShots += sanitizedShots.length;

  sanitizedScenes.push({
    scene_id: sceneId,
    narration: sceneNarration,
    evidence_ids: uniqueEvidence,
    evidence_uuids: uniqueEvidence.map((id) => evidenceMap[id]),
    shots: sanitizedShots,
  });
}

if (totalShots !== Number(ctx.target_shots)) {
  throw new Error(
    'total shot count mismatch: ' + totalShots +
    ', required exactly ' + ctx.target_shots
  );
}

const primarySubjectCounts = new Map();
for (const scene of sanitizedScenes) {
  for (const shot of scene.shots) {
    const primary = String(shot.must_show?.[0] ?? '').trim();
    const key = primary.toLowerCase();
    if (key) {
      primarySubjectCounts.set(
        key,
        Number(primarySubjectCounts.get(key) || 0) + 1
      );
    }
  }
}

for (const scene of sanitizedScenes) {
  for (const shot of scene.shots) {
    const primary = String(shot.must_show?.[0] ?? '').trim();
    const secondary = String(shot.must_show?.[1] ?? '').trim();
    const primaryRepeated =
      Number(primarySubjectCounts.get(primary.toLowerCase()) || 0) > 1;

    let fallbackQuery = primary;

    if (!fallbackQuery) {
      throw new Error(shot.shot_id + ' cannot build deterministic fallback query');
    }

    const existing = shot.queries_en.slice(0, 2).map(
      (value) => String(value ?? '').trim().toLowerCase()
    );
    if (existing.includes(fallbackQuery.toLowerCase())) {
      fallbackQuery = (
        fallbackQuery + ' sample'
      ).trim();
    }

    const fallbackWords = fallbackQuery.split(/\s+/u).filter(Boolean);
    if (
      fallbackWords.length < 1 ||
      fallbackWords.length > 4 ||
      fallbackQuery.length > 80
    ) {
      throw new Error(
        shot.shot_id +
        ' deterministic fallback query invalid: ' +
        fallbackQuery
      );
    }

    shot.queries_en[2] = fallbackQuery;
  }
}

const joinedNarration = clean(
  sanitizedScenes.map((scene) => scene.narration).join(' ')
);
if (!joinedNarration) {
  throw new Error('canonical narration is empty');
}

if (
  !/^(?:\p{Lu}|\d)/u.test(joinedNarration) ||
  !/[.!?…]$/u.test(joinedNarration)
) {
  throw new Error('canonical continuous narration must start normally and end as a complete utterance');
}


const hasUkrainianLexicalLeak = (value) => {
  const text = String(value ?? '').toLowerCase();
  if (/[ыэъё]/iu.test(text)) return true;

  const words = text
    .split(/[^\p{L}]+/u)
    .filter(Boolean);
  const russianOnlyCommon = new Set([
    'это','этот','эта','эти','его','её','ее','затем','потом',
    'сначала','который','которая','которые','чтобы'
  ]);

  return words.some((word) => russianOnlyCommon.has(word));
};

if (
  String(ctx.language_code) === 'uk' &&
  hasUkrainianLexicalLeak(joinedNarration)
) {
  throw new Error('Ukrainian narration contains Russian lexical/spelling forms');
}

const words = joinedNarration.split(/\s+/u).filter(Boolean);
const maxSceneWordsForSafety =
  Number(ctx.target_duration_seconds) <= 15 ? 10 : 14;
const hardWordMin = Math.max(
  Number(ctx.target_scenes) * 2,
  Math.floor(Number(ctx.word_min) * 0.70)
);
const hardWordMax = Math.min(
  Number(ctx.target_scenes) * maxSceneWordsForSafety,
  Math.ceil(Number(ctx.word_max) * 1.35)
);
if (words.length < hardWordMin || words.length > hardWordMax) {
  throw new Error(
    'canonical narration word count exceeds anti-runaway envelope: ' +
    words.length + ', allowed ' + hardWordMin + '-' + hardWordMax
  );
}

const usage = body.usageMetadata && typeof body.usageMetadata === 'object'
  ? body.usageMetadata
  : {};

return {
  json: {
    script_run_id: ctx.script_run_id,
    model: ctx.model,
    storyboard: {
      narration: joinedNarration,
      scenes: sanitizedScenes,
    },
    narration_word_count: words.length,
    scene_count: sanitizedScenes.length,
    shot_count: totalShots,
    usage,
  },
};

const ctx = $('Begin Script').first().json;
const runId = String(ctx.script_run_id ?? '').trim();
if (!runId) {
  throw new Error('cannot record script failure: script_run_id missing');
}

const errorObject =
  $json.error && typeof $json.error === 'object' && !Array.isArray($json.error)
    ? $json.error
    : {};

const candidates = [
  errorObject.message,
  $json.message,
  $json.description,
  typeof $json.error === 'string' ? $json.error : null,
];

const message = candidates.find(
  (value) => typeof value === 'string' && value.trim().length > 0
) ?? 'unspecified M5 workflow failure';

return {
  json: {
    script_run_id: runId,
    error_message: ('M5 script workflow failed: ' + message.trim()).slice(0, 4000),
  },
};

const ctx = $('Build Script Prompt').first().json;
const firstResponse = $('Generate Storyboard').first().json;
const source = $json ?? {};
const errorObject =
  source.error && typeof source.error === 'object' && !Array.isArray(source.error)
    ? source.error
    : {};

const validationError = [
  errorObject.message,
  source.message,
  source.description,
  typeof source.error === 'string' ? source.error : null,
].find((value) => typeof value === 'string' && value.trim().length > 0)
  ?? 'first storyboard failed validation';

const firstBody =
  firstResponse.body && typeof firstResponse.body === 'object'
    ? firstResponse.body
    : firstResponse;
const candidate = Array.isArray(firstBody.candidates)
  ? firstBody.candidates[0]
  : null;
const parts = Array.isArray(candidate?.content?.parts)
  ? candidate.content.parts
  : [];
const previousOutput = parts
  .filter((part) => part && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

if (!previousOutput) {
  throw new Error('cannot repair storyboard: first Gemini output is empty');
}

const systemMessage = [
  ctx.system_message,
  'You are repairing a previous JSON storyboard that failed deterministic validation.',
  'Return a complete replacement JSON object only.',
  'Do not explain the repair.',
].join(' ');

const userMessage = [
  ctx.user_message,
  '',
  'PREVIOUS OUTPUT FAILED VALIDATION:',
  validationError,
  '',
  'PREVIOUS OUTPUT:',
  previousOutput,
  '',
  'REPAIR REQUIREMENTS:',
  '- CRITICAL: visual_intent, every must_show item, every must_not_show item, and every queries_en item MUST be English only, even when narration is Polish, Russian, or Ukrainian;',
  '- if the validation error says visual metadata must be English, preserve narration, scene_id, shot_id, evidence_ids, scene order and factual meaning; repair/translate only the visual metadata fields needed to satisfy the English contract;',

  '- return a complete replacement object, not a patch;',
  '- preserve the existing scene and shot structure when it already has the required counts; do not merge, delete, reorder, or renumber valid scenes/shots just to repair narration;',
  '- preserve only facts supported by the supplied evidence;',
  '- EXACT scene count must be ' + ctx.target_scenes + ';',,
  '- EXACT total shot count must be ' + ctx.target_shots + ';',,
  '- every scene must contain exactly one shot;',,
  '- every scene narration must remain an exact contiguous visual-cut segment within the scene word bounds stated in the original contract; it MAY start as a continuation fragment or end mid-sentence because the voiceover is continuous;',,
  '- if a segment begins with a relative/anaphoric word, resolve its actual antecedent from the previous narration; do not force the previous shot primary when the previous narration introduced another referent after it; when the antecedent is the previous visual primary, keep it unless the current segment explicitly names a new concrete primary; never use an object unrelated to the actual antecedent/current clause;',,
  '- visual_intent must describe a concrete real visible subject, action, apparatus, material, location, or physical result;',,
  '- must_show[0] must be the strongest concrete searchable physical subject; optional secondary anchors may add useful visible context and must not be generic placeholders;',
  '- if a flow/current/reaction is hidden inside a closed conduit or machine, make that conduit/machine the primary must_show instead of requiring the hidden process itself to be visible;',
  '- secondary must_show anchors must add an independent visible subject/context; never restate, synonymize, or describe a component/detail of must_show[0] (for example water turbine + turbine blades);',,
  '- must_show must contain 1-3 short independent English visual anchors, each 1-3 words;',,
  '- queries_en must contain exactly 3 distinct concise English queries tied to the intended visible subject;',,
  '- queries 1 and 2 must retain a distinctive primary-subject term; query 3 must be a short robust fallback centered on the primary subject;',,
  '- preferred_media_type must be exactly photo; do not request diagrams, illustrations, schematics, infographics, icons, vectors, maps, documents, slides, text cards, or decorative stock imagery;',,
  '- do not use filler search words such as stunning, beautiful, scenery, wallpaper, aesthetic, background, cinematic, icon, vector, clipart, illustration, diagram, schematic, or infographic;',,
  '- use about ' + ctx.target_words + ' narration words as a planning target; real TTS timing later is authoritative;',,
  '- for Ukrainian output, use standard Ukrainian vocabulary only and do not silently mix Russian lexical forms;',,
  '- scene IDs must be sequential S1..S' + ctx.target_scenes + ';',,
  '- each shot ID must be the matching scene ID plus -A;',,
  '- top-level narration must exactly equal scene narrations joined with one space;',,
  '- every scene must cite valid supplied evidence IDs;',,
  '- do not include provider names, URLs, asset IDs, or filenames in shot fields;',,
].join('\n');

return {
  json: {
    script_run_id: ctx.script_run_id,
    model: ctx.model,
    system_message: systemMessage,
    user_message: userMessage,
  },
};

const providerError = $json && $json.error;
if (providerError) {
  const providerMessage = String(
    providerError.description ||
    providerError.message ||
    'Gemini provider request failed'
  );
  throw new Error(
    'Gemini provider failed after transient retries: ' + providerMessage
  );
}

const ctx = $('Build Script Prompt').first().json;
const response = $json ?? {};

const statusCode = Number(response.statusCode ?? response.status ?? 0);
if (statusCode < 200 || statusCode > 299) {
  const providerMessage =
    response.body?.error?.message ??
    response.error?.message ??
    response.message ??
    'Gemini request failed';
  throw new Error('Gemini HTTP ' + statusCode + ': ' + String(providerMessage));
}

const body = response.body && typeof response.body === 'object'
  ? response.body
  : response;

const candidate = Array.isArray(body.candidates) ? body.candidates[0] : null;
const parts = Array.isArray(candidate?.content?.parts) ? candidate.content.parts : [];
const rawText = parts
  .filter((part) => part && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('Gemini returned no text content');
}

const normalizedRawText = rawText;

const parseModelJson = (value) => {
  const original = String(value ?? '').trim();
  const text = original
    .replace(/^\x60\x60\x60(?:json)?\s*/iu, '')
    .replace(/\s*\x60\x60\x60$/u, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (primaryError) {
    let start = -1;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === '{' || text[i] === '[') {
        start = i;
        break;
      }
    }
    if (start < 0 || text.slice(0,start).trim()) {
      throw primaryError;
    }

    const stack = [];
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];

      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (ch === '\\') {
          escaped = true;
          continue;
        }
        if (ch === '"') inString = false;
        continue;
      }

      if (ch === '"') {
        inString = true;
        continue;
      }

      if (ch === '{' || ch === '[') {
        stack.push(ch);
        continue;
      }

      if (ch === '}' || ch === ']') {
        if (!stack.length) break;
        const open = stack[stack.length - 1];
        if (
          (open === '{' && ch !== '}') ||
          (open === '[' && ch !== ']')
        ) {
          throw primaryError;
        }
        stack.pop();

        if (!stack.length) {
          const candidate = text.slice(start,i + 1);
          const remainder = text.slice(i + 1).trim();
          if (remainder && !/^[}\]\s]+$/u.test(remainder)) {
            throw primaryError;
          }
          return JSON.parse(candidate);
        }
      }
    }

    throw primaryError;
  }
};

let parsed;
try {
