}

const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const narration = clean(parsed.narration);
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];

if (scenes.length !== Number(ctx.target_scenes)) {
