function withStableMeasurement(row) {
  const narration = String(row.storyboard?.narration ?? '').trim();
  if (!narration) return row;
  let duration = Number(row.measured_duration_ms);
  for (let runIndex = 0; runIndex < 5; runIndex++) {
    let items;
    try { items = $('Normalize Timing Stability B').all(0, runIndex); }
    catch { break; } // This bounded confirmation run has not executed.
    for (const item of items) {
      const sample = item.json ?? {};
      if (String(sample.storyboard?.narration ?? '').trim() === narration &&
          Number.isFinite(Number(sample.stability_median_ms)) &&
          Number(sample.stability_median_ms) > 0) {
        duration = Number(sample.stability_median_ms);
      }
    }
  }
  return {...row, measured_duration_ms: duration};
}

