      ? firstResponse.body
      : firstResponse;
  const firstUsage =
    firstBody?.usageMetadata && typeof firstBody.usageMetadata === 'object'
      ? firstBody.usageMetadata
      : {};
  p2 = {
    ...p1,
    storyboard: p1.storyboard,
    usage: mergeUsage(firstBuild?.prior_usage ?? p1.usage ?? {}, firstUsage),
  };
} else {
  p2 = withStableMeasurement(incoming);
}
const current = p2.storyboard;
if (!current || typeof current !== 'object') throw new Error('second timing repair storyboard missing');

const target = Number(p2.target_duration_ms);
const d1 = Number(p1.measured_duration_ms);
const d2 = Number(p2.measured_duration_ms);
const w1 = Number(p1.narration_word_count);
const w2 = Number(p2.narration_word_count);
const c1 = Array.from(String(p1.storyboard?.narration ?? '')).length;
const c2 = Array.from(String(p2.storyboard?.narration ?? '')).length;

if (![target,d1,d2,w1,w2,c1,c2].every(Number.isFinite) || target <= 0 || d1 <= 0 || d2 <= 0) {
  throw new Error('second timing repair interpolation context invalid');
}

const clamp = (v,min,max) => Math.max(min,Math.min(max,v));
let targetWords;
let targetChars;

if (Math.abs(d2-d1) >= 500 && Math.abs(w2-w1) >= 1) {
  targetWords = Math.round(w1 + ((target-d1) * (w2-w1) / (d2-d1)));
} else {
  targetWords = Math.round(w2 * target / d2);
}
if (Math.abs(d2-d1) >= 500 && Math.abs(c2-c1) >= 5) {
  targetChars = Math.round(c1 + ((target-d1) * (c2-c1) / (d2-d1)));
} else {
  targetChars = Math.round(c2 * target / d2);
}

const maxSceneWords = Number(ctx.target_duration_seconds) <= 15 ? 10 : 14;
const hardWordMin = Math.max(
  Number(ctx.target_scenes) * 2,
  Math.floor(Number(ctx.word_min) * 0.70)
);
const hardWordMax = Math.min(
  Number(ctx.target_scenes) * maxSceneWords,
  Math.ceil(Number(ctx.word_max) * 1.35)
);
targetWords = clamp(targetWords, hardWordMin, hardWordMax);
targetChars = clamp(targetChars, 100, 2000);

const sceneCount = Number(ctx.target_scenes);
// Preserve relative semantic space instead of forcing equally long scenes.
// Use the original narration, before successive timing rewrites lose detail.
const originalScenes = p1.storyboard.scenes;
if (originalScenes.length !== sceneCount) throw new Error('original scene count changed');
const weights = originalScenes.map(scene => String(scene.narration).trim().split(/\s+/u).length);
const weightTotal = weights.reduce((a,b) => a+b,0);
const desired = weights.map(weight => targetWords * weight / weightTotal);
const sceneWordTargets = desired.map(value => Math.max(2,Math.min(maxSceneWords,Math.floor(value))));
let assigned = sceneWordTargets.reduce((a,b) => a+b,0);
while (assigned !== targetWords) {
  const add = assigned < targetWords;
  const eligible = sceneWordTargets.map((value,index) => ({value,index}))
    .filter(({value}) => add ? value < maxSceneWords : value > 2)
    .sort((a,b) => add
      ? (desired[b.index]-b.value)-(desired[a.index]-a.value)
      : (a.value-desired[a.index])-(b.value-desired[b.index]));
  if (!eligible.length) throw new Error('cannot allocate narration word targets');
  const chosen = add ? eligible[0] : eligible[eligible.length-1];
  sceneWordTargets[chosen.index] += add ? 1 : -1;
  assigned += add ? 1 : -1;
}

const direction = d2 < target ? 'LONGER' : 'SHORTER';
const baseUserMessage = String(ctx.user_message ?? '')
  .replace(/^TARGET NARRATION WORD COUNT:.*$/mu, '')
  .replace(/^- count the narration words before returning JSON;.*$/mu, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const systemMessage = [
  'You perform a precision narration timing repair for an already factually validated storyboard.',
  'Preserve the original subject, action, required objects and causal direction. Shorten wording, never delete a necessary argument or replace content with filler adjectives.',
  'Preserve every non-narration field exactly.',
  'Return a complete replacement storyboard JSON object only.',
].join(' ');

const userMessage = [
  'TOPIC: ' + String(ctx.topic ?? ''),
  'LANGUAGE: ' + String(ctx.language_code ?? ''),
  'ORIGINAL MEANING TO PRESERVE:',
  JSON.stringify(p1.storyboard.scenes.map(s => ({scene_id:s.scene_id,narration:s.narration}))),
  fallbackFromFirstRepair
    ? 'SEMANTIC FALLBACK: the previous timing rewrite was rejected before TTS; regenerate from ORIGINAL MEANING only.'
    : 'CURRENT MEASURED STORYBOARD TO REPAIR:',
  JSON.stringify(current),
  '',
  'REAL TTS MEASUREMENTS:',
  'probe 1: ' + w1 + ' words, ' + c1 + ' characters, ' + d1 + ' ms',
  'probe 2: ' + w2 + ' words, ' + c2 + ' characters, ' + d2 + ' ms',
  'target: ' + target + ' ms +/- ' + p2.tolerance_ms + ' ms',
  '',
  'INTERPOLATED TARGET:',
  'timing target word count (guidance): about ' + targetWords,
  'preferred per-scene word counts in scene order (guidance): ' + sceneWordTargets.join(', '),
  'approximate target character count including spaces: ' + targetChars,
  'direction from current version: make narration ' + direction,
  '',
  'RULES:',
  '- preserve exactly ' + ctx.target_scenes + ' scenes and ' + ctx.target_shots + ' shots;',
  '- preserve every scene_id, evidence_ids, shot_id, visual_intent, must_show, must_not_show, queries_en, and preferred_media_type unchanged;',
  '- modify only top-level narration and each scene narration;',
  '- preserve factual meaning; do not add unsupported facts;',
  '- aim near ' + targetWords + ' total words, but preserve complete factual meaning even if the natural result differs slightly;',
  '- per-scene word counts are preferences only; redistribute words between scenes when needed to preserve subjects, objects and causal meaning;',
  '- never pad a scene with generic adjectives just to hit a count; never drop a required object to shorten it;',
  '- FINAL narration should be close to ' + targetChars + ' characters including spaces;',
  '- each scene narration is a contiguous visual segment, not necessarily a complete sentence; visual scene boundaries may occur inside a sentence; the joined narration must remain a natural complete utterance ending with . ! ? or …;',
  '- for Ukrainian use standard Ukrainian vocabulary only and no Russian lexical forms;',
  '- top-level narration must exactly equal all scene narrations joined with one space;',
  '- output valid JSON only.',
].join('\n');

return {json:{
  script_run_id: p2.script_run_id,
  model: p2.model,
  prior_usage: p2.usage ?? {},
  target_precision_words: targetWords,
  target_precision_chars: targetChars,
  target_scene_word_counts: sceneWordTargets,
  semantic_fallback_from_first_repair: fallbackFromFirstRepair,
  system_message: systemMessage,
  user_message: userMessage,
}};

const providerError = $json && $json.error;
if (providerError) {
  const providerMessage = String(
    providerError.description ||
    providerError.message ||
    'Gemini provider request failed'
  );
  throw new Error(
    'Gemini provider failed after transient retries: ' + providerMessage
  );
}

const ctx = $('Build Script Prompt').first().json;
const response = $json ?? {};

const statusCode = Number(response.statusCode ?? response.status ?? 0);
if (statusCode < 200 || statusCode > 299) {
  const providerMessage =
    response.body?.error?.message ??
    response.error?.message ??
    response.message ??
    'Gemini request failed';
  throw new Error('Gemini HTTP ' + statusCode + ': ' + String(providerMessage));
}

const body = response.body && typeof response.body === 'object'
  ? response.body
  : response;

const candidate = Array.isArray(body.candidates) ? body.candidates[0] : null;
const parts = Array.isArray(candidate?.content?.parts) ? candidate.content.parts : [];
const rawText = parts
  .filter((part) => part && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('Gemini returned no text content');
}

const normalizedRawText = rawText;

const parseModelJson = (value) => {
  const original = String(value ?? '').trim();
  const text = original
    .replace(/^\x60\x60\x60(?:json)?\s*/iu, '')
    .replace(/\s*\x60\x60\x60$/u, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (primaryError) {
    let start = -1;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === '{' || text[i] === '[') {
        start = i;
        break;
      }
    }
    if (start < 0 || text.slice(0,start).trim()) {
      throw primaryError;
    }

    const stack = [];
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];

      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (ch === '\\') {
          escaped = true;
          continue;
        }
        if (ch === '"') inString = false;
        continue;
      }

      if (ch === '"') {
        inString = true;
        continue;
      }

      if (ch === '{' || ch === '[') {
        stack.push(ch);
        continue;
      }

      if (ch === '}' || ch === ']') {
        if (!stack.length) break;
        const open = stack[stack.length - 1];
        if (
          (open === '{' && ch !== '}') ||
          (open === '[' && ch !== ']')
        ) {
          throw primaryError;
        }
        stack.pop();

        if (!stack.length) {
          const candidate = text.slice(start,i + 1);
          const remainder = text.slice(i + 1).trim();
          if (remainder && !/^[}\]\s]+$/u.test(remainder)) {
            throw primaryError;
          }
          return JSON.parse(candidate);
        }
      }
    }

    throw primaryError;
  }
};

let parsed;
try {
  parsed = parseModelJson(normalizedRawText);
} catch (error) {
  throw new Error('Gemini returned invalid JSON: ' + error.message);
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('Gemini storyboard root must be an object');
}
if (parsed.error) {
  throw new Error('Gemini could not build storyboard: ' + String(parsed.error));
}

const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const narration = clean(parsed.narration);
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];

if (scenes.length !== Number(ctx.target_scenes)) {
  throw new Error(
    'scene count mismatch: ' + scenes.length +
    ', required exactly ' + ctx.target_scenes
  );
}

const evidenceMap = ctx.evidence_map && typeof ctx.evidence_map === 'object'
  ? ctx.evidence_map
  : {};
const allowedEvidence = new Set(Object.keys(evidenceMap));
const allowedMedia = new Set(['photo']);
const providerPattern = /\b(pexels|pixabay|wikimedia|unsplash|openverse)\b|https?:\/\//i;

const sanitizedScenes = [];
const globalShotIds = new Set();
let totalShots = 0;

for (let i = 0; i < scenes.length; i++) {
  const scene = scenes[i];
  if (!scene || typeof scene !== 'object' || Array.isArray(scene)) {
    throw new Error('scene ' + (i + 1) + ' must be an object');
  }

  const expectedSceneId = 'S' + (i + 1);
  const sceneId = clean(scene.scene_id);
  if (sceneId !== expectedSceneId) {
    throw new Error('scene_id must be sequential: expected ' + expectedSceneId);
  }

  const sceneNarration = clean(scene.narration);
  if (!sceneNarration) {
    throw new Error(sceneId + ' narration is empty');
  }
  const sceneWords = sceneNarration.split(/\s+/u).filter(Boolean);
  const minSceneWords = 2;
  const maxSceneWords = Number(ctx.target_duration_seconds) <= 15 ? 10 : 14;
  if (sceneWords.length < minSceneWords) {
    throw new Error(
      sceneId + ' narration is too short for a semantic scene: ' +
      sceneWords.length + ', minimum ' + minSceneWords
    );
  }
  if (sceneWords.length > maxSceneWords) {
    throw new Error(
      sceneId + ' narration is too long for visual pacing: ' +
      sceneWords.length + ', maximum ' + maxSceneWords
    );
  }
  if (!/[\p{L}\d]/u.test(sceneNarration)) {
    throw new Error(sceneId + ' narration segment has no lexical content');
  }

  const evidenceIds = Array.isArray(scene.evidence_ids)
    ? scene.evidence_ids.map(clean)
    : [];
  const uniqueEvidence = [...new Set(evidenceIds)];
  if (
    uniqueEvidence.length < 1 ||
    uniqueEvidence.length > 4 ||
    uniqueEvidence.length !== evidenceIds.length ||
    uniqueEvidence.some((id) => !allowedEvidence.has(id))
  ) {
    throw new Error(sceneId + ' has invalid evidence_ids');
  }

  const shots = Array.isArray(scene.shots) ? scene.shots : [];
  if (shots.length !== 1) {
    throw new Error(sceneId + ' must contain exactly 1 shot');
  }

  const sanitizedShots = [];
  for (let j = 0; j < shots.length; j++) {
    const shot = shots[j];
    if (!shot || typeof shot !== 'object' || Array.isArray(shot)) {
      throw new Error(sceneId + ' shot ' + (j + 1) + ' must be an object');
    }

    const shotId = clean(shot.shot_id);
    const expectedSuffix = String.fromCharCode(65 + j);
    const expectedShotId = sceneId + '-' + expectedSuffix;
    if (shotId !== expectedShotId || globalShotIds.has(shotId)) {
      throw new Error('invalid or duplicate shot_id: ' + shotId);
    }
    globalShotIds.add(shotId);

    const visualIntent = clean(shot.visual_intent);
    if (visualIntent.length < 12 || visualIntent.length > 400) {
      throw new Error(shotId + ' visual_intent is invalid');
    }

    const rawMustShow = Array.isArray(shot.must_show)
      ? shot.must_show.map(clean).filter(Boolean)
      : [];
    const mustNotShow = Array.isArray(shot.must_not_show)
      ? shot.must_not_show.map(clean).filter(Boolean)
      : [];
    if (rawMustShow.length < 1 || rawMustShow.length > 3 || mustNotShow.length > 6) {
      throw new Error(shotId + ' must_show/must_not_show is invalid');
    }
    if (rawMustShow.some((item) => {
      const count = item.split(/\s+/u).filter(Boolean).length;
      return count < 1 || count > 3 || item.length > 60;
    })) {
      throw new Error(shotId + ' must_show items must be short domain anchors');
    }

    const primaryGeneric = new Set([
      'thing','item','object','generic','concept','process','action','method',
      'system','technology','material','surface','area','scene','background',
      'environment','result','product','component','part'
    ]);
    const secondaryGeneric = new Set([
      'thing','item','object','device','equipment','machine','tool','system',
      'process','action','method','technology','material','surface','area',
      'place','location','result','product','structure','environment',
      'background','scene','facility','component','part'
    ]);
    const anchorWords = (value) => String(value || '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g,' ')
      .split(/\s+/u)
      .filter(Boolean);

    const sourceQueries = Array.isArray(shot.queries_en)
      ? shot.queries_en.map(clean).filter(Boolean)
      : [];
    if (sourceQueries.length !== 3) {
      throw new Error(shotId + ' queries_en is invalid');
    }

    const mustShow = [
      rawMustShow[0],
      ...rawMustShow.slice(1).filter((anchor) => {
        const words = anchorWords(anchor);
        return words.length > 0 && !words.every((word) => secondaryGeneric.has(word));
      }),
    ];

    const primaryWords = anchorWords(mustShow[0]);
    const primaryTerms = primaryWords.filter(
      (word) => !primaryGeneric.has(word)
    );
    if (primaryTerms.length < 1) {
      throw new Error(
        shotId + ' must_show[0] lacks a concrete/searchable primary subject or exact equipment anchor'
      );
    }

    const processGeneric = secondaryGeneric;
    const secondaryTerms = mustShow
      .slice(1)
      .flatMap(anchorWords)
      .filter((word) => !processGeneric.has(word));

    const queries = sourceQueries.map((query,index) => {
      const words = query.split(/\s+/u).filter(Boolean);
      const lower = new Set(words.map((word) => word.toLowerCase()));

      if (index === 2) {
        if (!secondaryTerms.length) {
          const hasPrimary = primaryTerms.some((term) => lower.has(term));
          if (hasPrimary || primaryTerms.length === 0) return query;
          return mustShow[0];
        }

        const hasSecondary = secondaryTerms.some((term) => lower.has(term));
        if (hasSecondary) return query;

        const primaryHint = primaryTerms.length
          ? primaryTerms[primaryTerms.length - 1]
          : '';
        const fallbackTerms = secondaryTerms.length >= 2
          ? secondaryTerms.slice(0,3)
          : [primaryHint, secondaryTerms[0]].filter(Boolean);
        return fallbackTerms.join(' ');
      }

      const hasPrimary = primaryTerms.some((term) => lower.has(term));
      if (hasPrimary || primaryTerms.length === 0) return query;

      const room = Math.max(0, 10 - primaryTerms.length);
      const baseWords = words.slice(0, room);
      return [...baseWords, ...primaryTerms].join(' ');
    });

    if (
      queries.slice(0,2).some(
        (query) => query.toLowerCase() === queries[2].toLowerCase()
      )
    ) {
      const suffix = secondaryTerms[0] || 'detail';
      queries[2] = (queries[2] + ' ' + suffix).trim();
    }

    const queryKeys = queries.map((q) => q.toLowerCase());
    if (
      queries.length !== 3 ||
      new Set(queryKeys).size !== queries.length ||
      queries.some((query,index) => {
        const count = query.split(/\s+/u).filter(Boolean).length;
        const minWords = index === 2 ? 1 : 2;
        return count < minWords || count > 10 || query.length > 120;
      })
    ) {
      throw new Error(shotId + ' queries_en is invalid');
    }

    const preferredMediaType = clean(shot.preferred_media_type).toLowerCase();
    if (!allowedMedia.has(preferredMediaType)) {
      throw new Error(shotId + ' preferred_media_type is invalid');
    }

    const queryFillerPattern = /\b(stunning|beautiful|scenery|wallpaper|aesthetic|background|cinematic|icon|vector|clipart|illustration|diagram|schematic|infographic|text card)\b/i;
    const visualNonPhotoPattern = /\b(wallpaper|icon|vector|clipart|illustration|diagram|schematic|infographic|text card)\b/i;
    if (
      queries.some((query) => queryFillerPattern.test(query)) ||
      visualNonPhotoPattern.test(visualIntent)
    ) {
      throw new Error(shotId + ' contains generic/non-photographic visual request');
    }

    const antiSelectionText = [
      visualIntent,
      ...mustShow,
      ...mustNotShow,
      ...queries,
    ].join(' ');
    if (providerPattern.test(antiSelectionText)) {
      throw new Error(shotId + ' contains provider/URL preselection');
    }

    sanitizedShots.push({
      shot_id: shotId,
      visual_intent: visualIntent,
      must_show: mustShow,
      must_not_show: mustNotShow,
      queries_en: queries,
      preferred_media_type: preferredMediaType,
    });
  }

  totalShots += sanitizedShots.length;

  sanitizedScenes.push({
    scene_id: sceneId,
    narration: sceneNarration,
    evidence_ids: uniqueEvidence,
    evidence_uuids: uniqueEvidence.map((id) => evidenceMap[id]),
    shots: sanitizedShots,
  });
}

if (totalShots !== Number(ctx.target_shots)) {
  throw new Error(
    'total shot count mismatch: ' + totalShots +
    ', required exactly ' + ctx.target_shots
  );
}

const primarySubjectCounts = new Map();
for (const scene of sanitizedScenes) {
  for (const shot of scene.shots) {
    const primary = String(shot.must_show?.[0] ?? '').trim();
    const key = primary.toLowerCase();
    if (key) {
      primarySubjectCounts.set(
        key,
        Number(primarySubjectCounts.get(key) || 0) + 1
      );
    }
  }
}

for (const scene of sanitizedScenes) {
  for (const shot of scene.shots) {
    const primary = String(shot.must_show?.[0] ?? '').trim();
    const secondary = String(shot.must_show?.[1] ?? '').trim();
    const primaryRepeated =
      Number(primarySubjectCounts.get(primary.toLowerCase()) || 0) > 1;

    let fallbackQuery = primary;

    if (!fallbackQuery) {
      throw new Error(shot.shot_id + ' cannot build deterministic fallback query');
    }

    const existing = shot.queries_en.slice(0, 2).map(
      (value) => String(value ?? '').trim().toLowerCase()
    );
    if (existing.includes(fallbackQuery.toLowerCase())) {
      fallbackQuery = (
        fallbackQuery + ' sample'
      ).trim();
    }

    const fallbackWords = fallbackQuery.split(/\s+/u).filter(Boolean);
    if (
      fallbackWords.length < 1 ||
      fallbackWords.length > 4 ||
      fallbackQuery.length > 80
    ) {
      throw new Error(
        shot.shot_id +
        ' deterministic fallback query invalid: ' +
        fallbackQuery
      );
    }

    shot.queries_en[2] = fallbackQuery;
  }
}

// SEMANTIC_PRESERVATION_GUARD_START
const _semanticStopwords = {
  en: new Set(['the','a','an','and','or','but','to','of','in','on','at','for','from','with','as','by','is','are','was','were','be','been','being','that','which','who','when','then','into','through']),
  pl: new Set(['i','a','ale','lub','oraz','do','w','we','z','ze','za','na','od','po','dla','przez','się','sie','gdy','jest','są','sa','to','ten','ta','te','tych','który','ktory','która','ktora','które','ktore','jako']),
  ru: new Set(['и','а','но','или','в','во','на','с','со','из','за','по','для','от','до','при','как','когда','это','этот','эта','эти','что','который','которая','которые']),
  uk: new Set(['і','й','а','але','або','в','у','на','з','із','за','по','для','від','до','при','як','коли','це','цей','ця','ці','що','який','яка','які']),
};
const _semanticNormalizeWord = (value) =>
  String(value ?? '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/\p{M}+/gu,'')
    .replace(/[^\p{L}\p{N}]+/gu,'')
    .trim();
const _semanticRawTokens = (value) =>
  String(value ?? '')
    .normalize('NFKD')
    .replace(/\p{M}+/gu,'')
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .map(_semanticNormalizeWord)
    .filter(Boolean);
const _semanticTokens = (value, languageCode) => {
  const stop = _semanticStopwords[String(languageCode ?? '')] ?? new Set();
  return _semanticRawTokens(value).filter((token) => !stop.has(token));
};
const _semanticSimilar = (left,right) => {
  const a=_semanticNormalizeWord(left);
  const b=_semanticNormalizeWord(right);
  if (!a || !b) return false;
  if (a === b) return true;
  const minLen=Math.min(a.length,b.length);
  if (minLen < 4) return false;
  let prefix=0;
  while (prefix < minLen && a[prefix] === b[prefix]) prefix++;
  return prefix >= Math.max(3,minLen - 2);
};
const _semanticNegated = (value, languageCode) => {
  const neg = {
    en:new Set(['not','no','never','without']),
    pl:new Set(['nie','bez','nigdy']),
    ru:new Set(['не','нет','без','никогда']),
    uk:new Set(['не','ні','без','ніколи']),
  }[String(languageCode ?? '')] ?? new Set();
  return _semanticRawTokens(value).some((token) => neg.has(token));
};
const _semanticNumbers = (value) =>
  _semanticRawTokens(value).filter((token) => /^\d+(?:[.,]\d+)?$/u.test(token));
const assertSemanticPreservation = (originalValue,candidateValue,label,languageCode) => {
  const original=String(originalValue ?? '').replace(/\s+/g,' ').trim();
  const candidate=String(candidateValue ?? '').replace(/\s+/g,' ').trim();
  if (!original || !candidate) throw new Error(label + ' semantic reference/candidate missing');

  const originalTokens=_semanticTokens(original,languageCode);
  const candidateTokens=_semanticTokens(candidate,languageCode);
  if (!originalTokens.length || !candidateTokens.length) {
    throw new Error(label + ' semantic content tokens missing');
  }

  const used=new Set();
  let preserved=0;
  for (const token of originalTokens) {
    let match=-1;
    for (let i=0;i<candidateTokens.length;i++) {
      if (used.has(i)) continue;
      if (_semanticSimilar(token,candidateTokens[i])) { match=i; break; }
    }
    if (match >= 0) {
      used.add(match);
      preserved++;
    }
