    fillerRoots.some((root) => token.startsWith(root)) &&
    !originalTokens.some((originalToken) => _semanticSimilar(originalToken,token))
  );
  if (novelFiller.length) {
    throw new Error(label + ' introduced generic filler modifiers: ' + novelFiller.join(','));
  }

  const originalNumbers=_semanticNumbers(original);
  const candidateNumbers=_semanticNumbers(candidate);
  if (JSON.stringify(originalNumbers) !== JSON.stringify(candidateNumbers)) {
    throw new Error(label + ' changed numeric facts');
  }
  if (_semanticNegated(original,languageCode) !== _semanticNegated(candidate,languageCode)) {
    throw new Error(label + ' changed negation polarity');
