      const surface = validatePrecisionSurface(
        text,
        'precision ' + option.source + ' scene ' + (i+1)
      );
      assertSemanticPreservation(
        original,
        surface.text,
        'precision ' + option.source + ' scene ' + (i+1),
        buildCtx.language_code
      );
