  narrations.length * 2,
  Math.floor(Number(buildCtx.word_min) * 0.70)
);
const hardWordMax = Math.min(
  narrations.length * maxSceneWords,
  Math.ceil(Number(buildCtx.word_max) * 1.35)
);
