    }

    throw primaryError;
  }
};

let parsed;
try {
  parsed = parseModelJson(normalizedRawText);
} catch (error) {
  throw new Error('Gemini returned invalid final duration JSON: ' + error.message);
}

const narrations = Array.isArray(parsed?.narrations)
  ? parsed.narrations.map((value) => String(value ?? '').replace(/\s+/g,' ').trim())
  : [];
const base = JSON.parse(JSON.stringify(ctx.base_storyboard));
if (!Array.isArray(base.scenes) || narrations.length !== base.scenes.length) {
  throw new Error('final duration narration count mismatch');
}

// SEMANTIC_PRESERVATION_GUARD_START
const _semanticStopwords = {
  en: new Set(['the','a','an','and','or','but','to','of','in','on','at','for','from','with','as','by','is','are','was','were','be','been','being','that','which','who','when','then','into','through']),
  pl: new Set(['i','a','ale','lub','oraz','do','w','we','z','ze','za','na','od','po','dla','przez','się','sie','gdy','jest','są','sa','to','ten','ta','te','tych','który','ktory','która','ktora','które','ktore','jako']),
  ru: new Set(['и','а','но','или','в','во','на','с','со','из','за','по','для','от','до','при','как','когда','это','этот','эта','эти','что','который','которая','которые']),
  uk: new Set(['і','й','а','але','або','в','у','на','з','із','за','по','для','від','до','при','як','коли','це','цей','ця','ці','що','який','яка','які']),
