  }

  const fillerRoots = {
    en:['huge','enormous','massive','powerful','efficient','clean','giant','impressive'],
    pl:['ogromn','wielk','potezn','wydajn','czyst','siln'],
    ru:['огромн','мощн','эффективн','чист','гигантск'],
