    }

    const secondaryTerms = mustShow
      .slice(1)
      .flatMap(anchorWords)
      .filter((word) => !secondaryGeneric.has(word));

    const queries = sourceQueries.map((query,index) => {
      const queryWords = query.split(/\s+/u).filter(Boolean);
      const lower = new Set(queryWords.map((word) => word.toLowerCase()));

      if (index === 2) {
        if (!secondaryTerms.length) {
          if (primaryTerms.some((term) => lower.has(term))) return query;
          return primary;
        }
        if (secondaryTerms.some((term) => lower.has(term))) return query;
        const primaryHint = primaryTerms[primaryTerms.length - 1] || '';
        return (secondaryTerms.length >= 2
