}

storyboard.narration = storyboard.scenes
  .map((scene) => scene.narration)
  .join(' ')
  .replace(/\s+/g,' ')
  .trim();
if (
  !/^(?:\p{Lu}|\d)/u.test(storyboard.narration) ||
  !/[.!?…]$/u.test(storyboard.narration)
