const source = $json ?? {};
const storyboard = source.storyboard;
if (!storyboard || !Array.isArray(storyboard.scenes) || !storyboard.scenes.length) {
  throw new Error('final duration repair storyboard missing');
}

const measuredMs = Number(source.measured_duration_ms);
const targetMs = Number(source.target_duration_ms);
if (!Number.isFinite(measuredMs) || measuredMs <= 0 || !Number.isFinite(targetMs) || targetMs <= 0) {
  throw new Error('final duration repair timing context invalid');
}

const currentNarration = String(storyboard.narration ?? '').trim();
const currentChars = Array.from(currentNarration).length;
const currentWords = currentNarration.split(/\s+/u).filter(Boolean).length;
if (!currentChars || !currentWords) {
  throw new Error('final duration repair narration is empty');
}

const toleranceMs = Number(source.tolerance_ms);
if (!Number.isFinite(toleranceMs) || toleranceMs <= 0) {
  throw new Error('final duration repair tolerance invalid');
}
const guardMs = Math.max(150, Math.round(toleranceMs * 0.50));
