const linearTarget = (key, fallback) => {
  if (samples.length < 3) return fallback;
  const xs = samples.map((row) => Number(row[key]));
  const ys = samples.map((row) => row.duration);
  const meanX = xs.reduce((a,b) => a+b,0) / xs.length;
  const meanY = ys.reduce((a,b) => a+b,0) / ys.length;
  const variance = xs.reduce((sum,x) => sum + (x-meanX)*(x-meanX),0);
  if (variance <= 0) return fallback;
  const covariance = xs.reduce(
    (sum,x,i) => sum + (x-meanX)*(ys[i]-meanY),
    0
  );
