  if (!Number.isFinite(slope) || slope <= 0) return fallback;
  const intercept = meanY - slope * meanX;
  const predicted = (repairTargetMs - intercept) / slope;
  return Number.isFinite(predicted) && predicted > 0
    ? Math.round(predicted)
