const fallbackChars = Math.max(40, Math.round(currentChars * ratio));
const predictedChars = linearTarget('chars', fallbackChars);
const directionSafeChars = directionalTarget(
  currentChars,
  fallbackChars,
  predictedChars
);
const targetChars = Math.max(
  40,
  Math.min(
    Math.round(currentChars * 1.30),
    Math.max(Math.round(currentChars * 0.70), directionSafeChars)
  )
);

const fallbackWords = Math.round(currentWords * ratio);
const predictedWords = linearTarget('words', fallbackWords);
const hardWordMin = Math.max(
  storyboard.scenes.length * 2,
  Math.floor(Number(buildCtx.word_min) * 0.70)
);
const hardWordMax = Math.min(
  storyboard.scenes.length *
    (Number(buildCtx.target_duration_seconds) <= 15 ? 10 : 14),
  Math.ceil(Number(buildCtx.word_max) * 1.35)
);
const directionSafeWords = directionalTarget(
  currentWords,
  fallbackWords,
  predictedWords
);
const targetWords = Math.max(
  hardWordMin,
  Math.min(hardWordMax, directionSafeWords)
);
if (
  (makeLonger && targetWords <= currentWords && targetChars <= currentChars) ||
  (!makeLonger && targetWords >= currentWords && targetChars >= currentChars)
) {
  throw new Error(
    'late timing target cannot move in required direction within hard bounds'
  );
}
const minSceneWords = 2;
const maxSceneWords = Number(buildCtx.target_duration_seconds) <= 15 ? 10 : 14;

const originalStoryboard = $('Normalize Timing Probe').first().json.storyboard;
const originalScenes =
  originalStoryboard && Array.isArray(originalStoryboard.scenes)
    ? originalStoryboard.scenes
    : [];
if (originalScenes.length !== storyboard.scenes.length) {
  throw new Error('immutable original scene count unavailable for final timing repair');
}
const originalSceneWords = originalScenes.map((scene) =>
  String(scene.narration ?? '').trim().split(/\s+/u).filter(Boolean).length
