  const eligible = rawSceneTargets
    .map((value,index) => ({value,index}))
    .filter(({value}) => value < maxSceneWords)
    .sort((a,b) =>
      (desiredSceneWords[b.index]-b.value) -
      (desiredSceneWords[a.index]-a.value)
    );
  if (!eligible.length) break;
  rawSceneTargets[eligible[0].index] += 1;
  sceneTargetSum += 1;
}
while (sceneTargetSum > targetWords) {
  const eligible = rawSceneTargets
    .map((value,index) => ({value,index}))
    .filter(({value,index}) => value > semanticFloors[index])
    .sort((a,b) =>
      (a.value-desiredSceneWords[a.index]) -
      (b.value-desiredSceneWords[b.index])
    );
  if (!eligible.length) break;
  const chosen=eligible[eligible.length-1];
  rawSceneTargets[chosen.index] -= 1;
  sceneTargetSum -= 1;
}

if (sceneTargetSum !== targetWords) {
  throw new Error(
    'cannot distribute final duration target words without violating semantic floors: ' +
    sceneTargetSum + ' vs ' + targetWords
  );
}

const rows = storyboard.scenes.map((scene,index) => ({
  scene: index + 1,
  target_words: rawSceneTargets[index],
  original_narration: String(originalScenes[index].narration ?? '').trim(),
  current_narration: String(scene.narration ?? '').trim(),
}));

const systemMessage = [
  'You perform one final timing correction for a short narration.',
  'Return only JSON with one key named narrations containing exactly ' +
    rows.length + ' strings.',
  'The immutable original_narration is the factual meaning source. current_narration is only an unaccepted timing draft.',
  'Do not add new facts. Preserve original subjects, actions, required objects and causal direction.',
  'Do not change any visual or evidence fields because they are not part of this response.',
].join(' ');

const direction = measuredMs < targetMs ? 'LONGER' : 'SHORTER';
const userMessage = [
  'LANGUAGE: ' + languageCode,
  'CURRENT MEASURED TTS: ' + measuredMs + ' ms',
  'TARGET TTS WINDOW CENTER: ' + targetMs + ' ms',
  'MEASURED CORRECTION AIM: ' + repairTargetMs + ' ms using the latest real TTS samples',
  'DIRECTION: make the complete narration ' + direction,
  'CURRENT TOTAL: ' + currentWords + ' words, ' + currentChars + ' characters including spaces',
  'TARGET TOTAL: about ' + targetWords + ' words and about ' + targetChars + ' characters including spaces',
  '',
  'LINES:',
  JSON.stringify(rows),
  '',
  'RULES:',
  '- return exactly ' + rows.length + ' narration strings in the same order;',
  '- preserve original_narration meaning for each line; current_narration may contain errors and is not a semantic source;',
  '- reuse original terminology when possible; do not replace concrete meaning with generic motion, force, size or decorative adjectives;',
  '- each line is a contiguous visual narration segment and may begin/end mid-sentence; joined in order, the lines must form one natural complete narration ending with . ! ? or …;',
  '- treat each target_words value as a preference, not a hard constraint; redistribute words to keep each line complete and natural;',
  '- aim near ' + targetWords + ' total words; preserving original meaning overrides an exact count;',
  '- approximate character target is ' + targetChars + ' characters including spaces;',
  '- use word counts only as timing guidance; real TTS measurement decides acceptance;',
  '- do not duplicate clauses or add unsupported details;',
  '- for Ukrainian use standard Ukrainian only; no Russian lexical/spelling forms;',
  '- output only JSON: {"narrations":["..."]}.',
].join('\n');

return {json:{
  script_run_id: source.script_run_id,
  model: source.model,
  base_storyboard: storyboard,
  prior_usage: source.usage ?? {},
  target_duration_ms: targetMs,
  repair_target_duration_ms: repairTargetMs,
  tolerance_ms: toleranceMs,
  target_chars: targetChars,
  target_words: targetWords,
  target_scene_word_counts: rawSceneTargets,
  system_message: systemMessage,
  user_message: userMessage,
}};

parameters.body:
={{ JSON.stringify({
  systemInstruction: { parts: [{ text: $json.system_message }] },
