  const coverage=preserved/originalTokens.length;
  const novel=candidateTokens.length-used.size;
  const allowedNovel=Math.max(1,Math.floor(candidateTokens.length*0.20));
  if (coverage < 0.60) {
    throw new Error(
      label + ' lost too much original semantic content: coverage ' +
      coverage.toFixed(3) + ', required >= 0.600'
    );
  }
  if (novel > allowedNovel) {
    throw new Error(
      label + ' introduced too many new content words: ' +
      novel + ', allowed ' + allowedNovel
    );
  }

  const fillerRoots = {
    en:['huge','enormous','massive','powerful','efficient','clean','giant','impressive'],
    pl:['ogromn','wielk','potezn','wydajn','czyst','siln'],
    ru:['огромн','мощн','эффективн','чист','гигантск'],
    uk:['величезн','потужн','ефективн','чист','гігантськ'],
  }[String(languageCode ?? '')] ?? [];
  const novelFiller = candidateTokens.filter((token) =>
    fillerRoots.some((root) => token.startsWith(root)) &&
    !originalTokens.some((originalToken) => _semanticSimilar(originalToken,token))
  );
  if (novelFiller.length) {
    throw new Error(label + ' introduced generic filler modifiers: ' + novelFiller.join(','));
  }

  const originalNumbers=_semanticNumbers(original);
  const candidateNumbers=_semanticNumbers(candidate);
  if (JSON.stringify(originalNumbers) !== JSON.stringify(candidateNumbers)) {
    throw new Error(label + ' changed numeric facts');
  }
  if (_semanticNegated(original,languageCode) !== _semanticNegated(candidate,languageCode)) {
    throw new Error(label + ' changed negation polarity');
  }
};
// SEMANTIC_PRESERVATION_GUARD_END

const buildCtx = $('Build Script Prompt').first().json;
const maxSceneWords = Number(buildCtx.target_duration_seconds) <= 15 ? 10 : 14;
const assertSceneSegment = (value,label) => {
  const text = String(value ?? '').trim();
  if (!/[\p{L}\d]/u.test(text)) {
    throw new Error(label + ' narration segment has no lexical content');
  }
};

const retryCounts = narrations.map(countWords);
for (let i = 0; i < retryCounts.length; i++) {
  if (retryCounts[i] < 2 || retryCounts[i] > maxSceneWords) {
    throw new Error(
      'exact word-count scene ' + (i + 1) +
      ' narration length outside 2-' + maxSceneWords + ' words: ' + retryCounts[i]
    );
  }
  assertSceneSegment(narrations[i], 'exact word-count scene ' + (i + 1));
}

const baseNarrations = base.scenes.map(
  (scene) => String(scene.narration ?? '').replace(/\s+/g,' ').trim()
);
const baseCounts = baseNarrations.map(countWords);
for (let i = 0; i < baseCounts.length; i++) {
  if (baseCounts[i] < 2 || baseCounts[i] > maxSceneWords) {
    throw new Error(
      'base final-duration scene ' + (i + 1) +
      ' narration length outside 2-' + maxSceneWords + ' words: ' + baseCounts[i]
    );
  }
  assertSceneSegment(baseNarrations[i], 'base final-duration scene ' + (i + 1));
}

const preFinalStoryboard =
  $('Build Final Measured Correction').first().json.base_storyboard;
const preFinalNarrations =
  preFinalStoryboard &&
  Array.isArray(preFinalStoryboard.scenes) &&
  preFinalStoryboard.scenes.length === narrations.length
    ? preFinalStoryboard.scenes.map(
        (scene) => String(scene.narration ?? '').replace(/\s+/g,' ').trim()
      )
    : [];
const preFinalCounts = preFinalNarrations.map(countWords);
for (let i = 0; i < preFinalCounts.length; i++) {
  if (preFinalCounts[i] < 2 || preFinalCounts[i] > maxSceneWords) {
    throw new Error(
      'pre-final scene ' + (i + 1) +
      ' narration length outside 2-' + maxSceneWords + ' words: ' + preFinalCounts[i]
    );
  }
  assertSceneSegment(preFinalNarrations[i], 'pre-final scene ' + (i + 1));
}

const targetWords = Number(ctx.target_words);
if (!Number.isInteger(targetWords) || targetWords <= 0) {
  throw new Error('exact word-count target invalid');
}

let totalWords = retryCounts.reduce((sum,count) => sum + count, 0);
let hybridized = false;

if (totalWords !== targetWords) {
  const sceneTargets =
    Array.isArray(ctx.target_scene_word_counts) &&
    ctx.target_scene_word_counts.length === narrations.length
      ? ctx.target_scene_word_counts.map(Number)
      : narrations.map(() => 0);

  // Reuse only earlier measured drafts from this same immutable storyboard.
  // Branch-dependent probes can be absent after semantic fallback.
  const originalScenes = $('Normalize Timing Probe').first().json.storyboard?.scenes;
  const measuredDrafts = [];
  for (const nodeName of ['Normalize Timing Probe 2','Normalize Timing Probe 3']) {
    let draft;
    try { draft = $(nodeName).first().json.storyboard; } catch { continue; }
    if (Array.isArray(draft?.scenes) && draft.scenes.length === narrations.length) {
      measuredDrafts.push(draft.scenes);
    }
  }

  let states = new Map();
  states.set(0, { lines: [], cost: 0 });

  for (let i = 0; i < narrations.length; i++) {
    const options = [];
    const addSemanticOption = (text,count,source) => {
      const normalized = String(text ?? '').replace(/\s+/g,' ').trim();
      if (!normalized || options.some(option => option.text === normalized)) return;
      if (count < 2 || count > maxSceneWords) return;
      try {
        assertSceneSegment(normalized, source + ' scene ' + (i+1));
        assertSemanticPreservation(
          originalScenes?.[i]?.narration,
          normalized,
          source + ' scene ' + (i+1),
          buildCtx.language_code
        );
      } catch {
        return;
      }
      options.push({text: normalized, count, source});
    };

    addSemanticOption(narrations[i], retryCounts[i], 'retry');
    if (baseNarrations[i] !== narrations[i]) {
      addSemanticOption(baseNarrations[i], baseCounts[i], 'base');
    }
    if (
      preFinalNarrations.length === narrations.length &&
      preFinalNarrations[i] !== narrations[i] &&
      preFinalNarrations[i] !== baseNarrations[i]
    ) {
      addSemanticOption(
        preFinalNarrations[i],
        preFinalCounts[i],
        'pre_final'
      );
    }

    for (const scenes of measuredDrafts) {
      if (scenes[i]?.scene_id !== originalScenes?.[i]?.scene_id) continue;
      const text = String(scenes[i]?.narration ?? '').replace(/\s+/g,' ').trim();
      if (!text || options.some(option => option.text === text)) continue;
      addSemanticOption(text,countWords(text),'measured');
    }

    if (!options.length) {
      throw new Error(
        'final measured word-count scene ' + (i+1) +
        ' has no semantic-valid narration option'
      );
    }

    const next = new Map();
    for (const [sum,state] of states.entries()) {
      for (const option of options) {
        const newSum = sum + option.count;

        const desired = Number(sceneTargets[i]);
        const sceneCost =
          Number.isFinite(desired) && desired > 0
            ? Math.abs(option.count - desired)
            : 0;
        const sourcePenalty = option.source === 'base' ? 0.001 : 0;
        const newCost = state.cost + sceneCost + sourcePenalty;
        const previous = next.get(newSum);

        if (!previous || newCost < previous.cost) {
          next.set(newSum, {
            lines: [...state.lines, option.text],
            cost: newCost,
          });
        }
      }
    }
    states = next;
  }

  const exact = states.get(targetWords);
  if (exact) {
    narrations = exact.lines;
    totalWords = targetWords;
    hybridized = true;
  } else {
    const completed = [...states.entries()]
      .filter(([,state]) => Array.isArray(state.lines) && state.lines.length === narrations.length)
      .sort((a,b) => {
        const deltaA = Math.abs(Number(a[0]) - targetWords);
        const deltaB = Math.abs(Number(b[0]) - targetWords);
        if (deltaA !== deltaB) return deltaA - deltaB;
        if (a[1].cost !== b[1].cost) return a[1].cost - b[1].cost;
        return Number(a[0]) - Number(b[0]);
      });

    if (!completed.length) {
      throw new Error('final measured word-count hybrid produced no complete narration');
    }

    const [nearestTotalRaw,nearest] = completed[0];
    const nearestTotal = Number(nearestTotalRaw);
    const allowedNearDelta = Math.max(2, Math.ceil(targetWords * 0.05));
    if (Math.abs(nearestTotal - targetWords) > allowedNearDelta) {
      throw new Error(
        'final measured word-count retry too far from target before TTS: got ' +
        nearestTotal + ', target ' + targetWords +
        ', allowed delta ' + allowedNearDelta
      );
    }

    // Word count is only a duration heuristic for stochastic Chirp synthesis.
    // Reuse the closest already-semantic-validated scene combination and let
    // the real Probe 5 + stability gate decide actual duration.
    narrations = nearest.lines;
    totalWords = nearestTotal;
    hybridized = true;
  }
}

// This is the last text correction after a measured TTS miss. Exact word count
// is preferred, but a tightly bounded nearest semantic hybrid may proceed because
// Chirp duration is stochastic; Probe 5 + stability remains the actual timing gate.
const originalSemanticScenes = $('Normalize Timing Probe').first().json.storyboard?.scenes;
if (!Array.isArray(originalSemanticScenes) || originalSemanticScenes.length !== narrations.length) {
  throw new Error('immutable original scenes unavailable for exact-word semantic validation');
}
for (let i=0;i<narrations.length;i++) {
  assertSemanticPreservation(
    originalSemanticScenes[i].narration,
    narrations[i],
    'exact word-count scene ' + (i+1),
    buildCtx.language_code
  );
}

const joined = narrations.join(' ');
if (
  !/^(?:\p{Lu}|\d)/u.test(joined) ||
  !/[.!?…]$/u.test(joined)
) {
  throw new Error('exact word-count joined narration must be a complete utterance');
}
const hasUkrainianLexicalLeak = (value) =>
  /[ыэъё]/iu.test(String(value ?? ''));

if (
  String($('Build Script Prompt').first().json.language_code ?? '') === 'uk' &&
  hasUkrainianLexicalLeak(joined)
) {
  throw new Error('Ukrainian exact word-count narration contains Russian lexical/spelling forms');
}

for (let i = 0; i < base.scenes.length; i++) {
  base.scenes[i].narration = narrations[i];
}
base.narration = joined;

const repairUsage = body.usageMetadata && typeof body.usageMetadata === 'object'
  ? body.usageMetadata
  : {};
const prior = ctx.prior_usage ?? {};
const toCount = (value) => Number.isFinite(Number(value)) ? Number(value) : 0;
const usage = {
  promptTokenCount:
    toCount(prior.promptTokenCount) + toCount(repairUsage.promptTokenCount),
  candidatesTokenCount:
    toCount(prior.candidatesTokenCount) + toCount(repairUsage.candidatesTokenCount),
  totalTokenCount:
    toCount(prior.totalTokenCount) + toCount(repairUsage.totalTokenCount),
};

return {json:{
  script_run_id: ctx.script_run_id,
  model: ctx.model,
  storyboard: base,
  narration_word_count: totalWords,
  target_word_count: targetWords,
  word_count_exact: totalWords === targetWords,
  deterministic_word_hybrid_used: hybridized,
  scene_count: base.scenes.length,
  shot_count: base.scenes.reduce(
    (sum,scene) => sum + (Array.isArray(scene.shots) ? scene.shots.length : 0),
    0
  ),
  usage,
}};

const source = $json ?? {};
const ctx = $('Build Script Prompt').first().json;
const languageCode = String(ctx.language_code ?? '');
const voices = {
  en: { locale: 'en-US', voice_name: 'en-US-Chirp3-HD-Algenib', sku_family: 'chirp3_hd' },
  pl: { locale: 'pl-PL', voice_name: 'pl-PL-Chirp3-HD-Enceladus', sku_family: 'chirp3_hd' },
  ru: { locale: 'ru-RU', voice_name: 'ru-RU-Wavenet-D', sku_family: 'wavenet' },
  uk: { locale: 'uk-UA', voice_name: 'uk-UA-Chirp3-HD-Enceladus', sku_family: 'chirp3_hd' },
};
const voice = voices[languageCode];
if (!voice) throw new Error('unsupported timing-probe language');
const narration = String(source.storyboard?.narration ?? '').trim();
if (!narration) throw new Error('timing probe narration is empty');
const productTargetDurationMs = Math.round(
  Number(ctx.target_duration_seconds) * 1000
);
const targetDurationMs = productTargetDurationMs;
const toleranceMs = languageCode === 'uk'
  ? 2000
  : Math.max(750, Math.round(productTargetDurationMs * 0.05));
const jobId = String($('When Executed by Another Workflow').first().json.job_id ?? '').trim();
if (!jobId) throw new Error('timing probe job_id missing');
return {
  json: {
    job_id: jobId,
    script_run_id: source.script_run_id,
    model: source.model,
    storyboard: source.storyboard,
    narration_word_count: source.narration_word_count,
    scene_count: source.scene_count,
    shot_count: source.shot_count,
    usage: source.usage ?? {},
    locale: voice.locale,
    voice_name: voice.voice_name,
    sku_family: voice.sku_family,
    character_count: Array.from(narration).length,
    probe_attempt: 5,
    probe_usage_key: 'm5-tts-probe:' + source.script_run_id + ':5',
    target_duration_ms: targetDurationMs,
    tolerance_ms: toleranceMs,
  },
};

const ctx = $('Prepare Timing Probe 5').first().json;
const response = $json ?? {};
const body = response.body && typeof response.body === 'object' ? response.body : response;
let statusCode = Number(response.statusCode ?? response.status ?? 0);
const audioBase64 = typeof body.audioContent === 'string' ? body.audioContent.trim() : '';
if (!statusCode && audioBase64) statusCode = 200;
const consumed = statusCode >= 200 && statusCode <= 299;
const base64Shape = audioBase64.length > 100 && /^[A-Za-z0-9+/]+={0,2}$/.test(audioBase64);
const success = consumed && base64Shape;
const providerMessage = body?.error?.message ?? response?.error?.message ?? response?.message ?? 'Google Cloud TTS timing probe failed';
return {json:{
  ...ctx,
  tts_http_status: statusCode,
  tts_consumed: consumed,
  tts_success: success,
  audio_base64: success ? audioBase64 : '',
  error_message: success ? '' : String(providerMessage).slice(0,3000),
}};

const ctx = $('Prepare Timing Probe 5').first().json;
const response = $json ?? {};
const body = response.body && typeof response.body === 'object' ? response.body : response;
const statusCode = Number(response.statusCode ?? response.status ?? 0);
const durationMs = Number(body.duration_ms);
if (statusCode !== 200 || body.status !== 'ready' || !Number.isInteger(durationMs) || durationMs <= 0) {
  const message = body?.message ?? body?.error ?? response?.error?.message ?? response?.message ?? 'media-worker timing probe failed';
  throw new Error('M5 timing probe failed: ' + String(message));
}
const deltaMs = Math.abs(durationMs - Number(ctx.target_duration_ms));
return {json:{
  script_run_id: ctx.script_run_id,
  model: ctx.model,
  storyboard: ctx.storyboard,
  narration_word_count: ctx.narration_word_count,
  scene_count: ctx.scene_count,
  shot_count: ctx.shot_count,
  usage: ctx.usage,
  measured_duration_ms: durationMs,
  target_duration_ms: ctx.target_duration_ms,
  tolerance_ms: ctx.tolerance_ms,
  duration_delta_ms: deltaMs,
  timing_ok: deltaMs <= Number(ctx.tolerance_ms),
  timing_stability_candidate:
    deltaMs <= Number(ctx.tolerance_ms) + 1000,
  origin_probe_attempt: Number(ctx.probe_attempt),
}};

const source = $('Canonicalize Final Storyboard').first().json;
const accepted = source.accepted_voiceover_candidate;
if (!accepted || typeof accepted !== 'object') {
  throw new Error('accepted voiceover candidate metadata missing');
}
const response = $json ?? {};
const body = response.body && typeof response.body === 'object'
  ? response.body
  : response;
let statusCode = Number(response.statusCode ?? response.status ?? 0);
if (!statusCode && body.status === 'ready') statusCode = 201;

const jobId = String(
  $('When Executed by Another Workflow').first().json.job_id ?? ''
).trim();
const expectedPath =
  '/data/voiceover-candidates/' + jobId + '/accepted.mp3';
const durationMs = Number(body.duration_ms);
const targetMs = Number(source.target_duration_ms);
const toleranceMs =
  Math.max(750, Math.round(targetMs * 0.05)) + 50;
const durationOk =
  Number.isInteger(durationMs) &&
  Math.abs(durationMs-targetMs) <= toleranceMs &&
  durationMs === Number(accepted.duration_ms);
const sha256 = String(body.sha256 ?? '').trim().toLowerCase();
const bytes = Number(body.bytes);
const sampleRate = Number(body.sample_rate);
const channels = Number(body.channels);
const codec = String(body.codec ?? '').trim().toLowerCase();
const storagePath = String(body.storage_path ?? '').trim();
const returnedJobId = String(body.job_id ?? '').trim();

const success =
  statusCode === 201 &&
  body.status === 'ready' &&
  returnedJobId === jobId &&
  storagePath === expectedPath &&
  durationOk &&
  /^[0-9a-f]{64}$/.test(sha256) &&
  Number.isInteger(bytes) && bytes > 0 &&
  Number.isInteger(sampleRate) && sampleRate > 0 &&
  Number.isInteger(channels) && channels > 0 &&
  codec === 'mp3';

if (!success) {
  const message =
    body?.message ??
    body?.error ??
    response?.error?.message ??
    response?.message ??
    'accepted voiceover candidate storage failed';
  throw new Error(
    'M5 accepted voiceover candidate storage failed: ' +
    String(message)
  );
}

return {json:{
  script_run_id: source.script_run_id,
  narration: source.storyboard.narration,
  locale: accepted.locale,
  voice_name: accepted.voice_name,
  sku_family: accepted.sku_family,
  usage_idempotency_key: accepted.usage_idempotency_key,
  storage_path: storagePath,
  audio_sha256: sha256,
  bytes,
  duration_ms: durationMs,
  sample_rate: sampleRate,
  channels,
  codec,
}};

parameters.query:
SELECT candidate_id::text AS candidate_id, duration_ms, audio_sha256
FROM factory.register_voiceover_candidate(
  $1::uuid,$2::text,$3::text,$4::text,$5::text,$6::text,
  $7::text,$8::text,$9::bigint,$10::integer,$11::integer,$12::integer,$13::text
);
